const rankNames = ['RECRUIT','JUNIOR ANALYST','FIELD INVESTIGATOR','SENIOR INVESTIGATOR','SPECIAL OPERATIONS AGENT','INTELLIGENCE DIRECTOR CANDIDATE'];
const freshState = () => ({ version:1, agentName:'', loggedIn:false, xp:0, currentMission:1, completedMissions:[], foundEvidence:['EVD-001'], boardItems:['EVD-001'], boardLinks:[], readMail:[], searchHistory:[], notes:'', history:[], flags:{viewedHuman:[], viewedVehicle:[], openedCase:[], forensic:[], calls:[], terminal:[]}, settings:{master:true, music:true, voice:true, subtitles:true, lowMotion:false, textSize:100}, terminalLog:[{text:'CIB TERMINAL // LOCAL SIMULATION', kind:'ok'},{text:'Ketik help untuk daftar perintah yang tersedia.',kind:''}], ui:{selectedHuman:null, selectedVehicle:null, selectedMail:'MSG-001', selectedEvidence:null, activeMap:'LOC-001'} });

const StateStore = {
  state: freshState(),
  load() {
    try { const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null'); if (saved && saved.version === 1) this.state = this.merge(freshState(), saved); } catch (error) { console.warn('Save invalid, using session state.', error); }
    return this.state;
  },
  merge(base, value) { const out = {...base, ...value, settings:{...base.settings,...(value.settings||{})}, flags:{...base.flags,...(value.flags||{})}, ui:{...base.ui,...(value.ui||{})}, terminalLog:Array.isArray(value.terminalLog)?value.terminalLog:base.terminalLog}; return out; },
  save(label = 'SYNCED') { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.state)); } catch (error) { console.warn('Local save unavailable.', error); } $('#taskbar-save-state').textContent = label; window.clearTimeout(this.saveTimer); this.saveTimer = window.setTimeout(() => { if ($('#taskbar-save-state')) $('#taskbar-save-state').textContent = 'SYNCED'; }, 1300); },
  reset() { this.state = freshState(); try { localStorage.removeItem(STORAGE_KEY); } catch {} }
};
StateStore.load();
const S = () => StateStore.state;

const rankFor = xp => Math.min(rankNames.length - 1, Math.floor(xp / 500));
const currentMission = () => missionDefs.find(m => m.id === S().currentMission) || missionDefs[missionDefs.length - 1];
const isUnlocked = mission => mission.id <= S().currentMission || S().completedMissions.includes(mission.id);
const getHuman = id => humans.find(item => item.id === id);
const getVehicle = id => vehicles.find(item => item.id === id);
const getEvidence = id => evidence.find(item => item.id === id);
const getMail = id => mail.find(item => item.id === id);
const addUnique = (array, value) => { if (!array.includes(value)) array.push(value); };

const AudioManager = { ctx:null, init() { if (!S().settings.master) return; try { this.ctx ||= new AudioContext(); } catch {} }, tone(freq=440, duration=.06, type='sine') { if (!S().settings.master || !this.ctx) return; const o=this.ctx.createOscillator(), g=this.ctx.createGain(); o.type=type; o.frequency.value=freq; g.gain.setValueAtTime(.035, this.ctx.currentTime); g.gain.exponentialRampToValueAtTime(.001, this.ctx.currentTime+duration); o.connect(g).connect(this.ctx.destination); o.start(); o.stop(this.ctx.currentTime+duration); }, click(){this.tone(520,.035)}, success(){this.tone(760,.08); window.setTimeout(()=>this.tone(980,.08),70)}, alert(){this.tone(240,.16,'square')} };
const NotificationManager = { push(title, message, kind='') { const toast=document.createElement('div'); toast.className=`toast ${kind}`; toast.innerHTML=`<p class="eyebrow">${esc(title)}</p><p>${esc(message)}</p>`; $('#toast-stack').appendChild(toast); AudioManager.alert(); window.setTimeout(()=>toast.remove(), 4600); } };

const DialogueEngine = {
  queue: [], index:0,
  show(lines, onDone) { if (!S().settings.subtitles) return onDone?.(); this.queue=lines; this.index=0; this.onDone=onDone; this.render(); $('#dialog-overlay').classList.remove('is-hidden'); AudioManager.click(); },
  render() { const line=this.queue[this.index]; if(!line){ this.close(); return; } const initials=line.speaker.split(' ').map(x=>x[0]).join('').slice(0,2); $('#dialog-overlay').innerHTML=`<div class="dialog-card"><div class="dialog-avatar" style="color:${line.color||'var(--cyan)'};border-color:${line.color||'var(--cyan)'}">${esc(initials)}</div><div><div class="dialog-speaker" style="color:${line.color||'var(--cyan)'}">${esc(line.speaker)}</div><p class="dialog-text">${esc(line.text)}</p></div><button class="btn btn-primary dialog-next" data-action="dialog-next">${this.index===this.queue.length-1?'SELESAI':'LANJUT'} <span>→</span></button></div>`; const speech=window.speechSynthesis; const Utterance=window.SpeechSynthesisUtterance; if(S().settings.voice && speech && Utterance){ try { speech.cancel(); const utter=new Utterance(line.text); utter.lang='id-ID'; utter.rate=line.rate||.98; utter.pitch=line.pitch||1; window.setTimeout(()=>{ try { speech.speak(utter); } catch {} },80); } catch {} } },
  next(){ this.index+=1; this.render(); },
  close(){ $('#dialog-overlay').classList.add('is-hidden'); $('#dialog-overlay').innerHTML=''; try { window.speechSynthesis?.cancel?.(); } catch {} this.onDone?.(); }
};

const WindowManager = {
  windows:new Map(), z:10, active:null,
  open(appId) { const app=APP_REGISTRY.find(item=>item.id===appId); if(!app)return; AudioManager.click(); let entry=this.windows.get(appId); if(entry){ entry.el.classList.remove('is-min'); this.focus(appId); return; } const el=document.createElement('article'); el.className='app-window'; el.dataset.app=appId; el.style.zIndex=++this.z; el.innerHTML=this.template(app); $('#window-layer').appendChild(el); entry={el, maximized:false}; this.windows.set(appId,entry); this.bindWindow(el,appId); this.focus(appId); renderApp(appId); renderTaskbar(); },
  template(app){ return `<div class="window-titlebar"><span class="window-icon">${esc(app.glyph)}</span><span class="window-title">${esc(app.label)}</span><span class="window-subtitle">CIB // LOCAL APP</span><div class="window-controls"><button class="window-control" data-window-action="minimize" title="Minimize">−</button><button class="window-control" data-window-action="maximize" title="Maximize">□</button><button class="window-control close" data-window-action="close" title="Close">×</button></div></div><div class="window-content"></div><div class="window-footer"><span>DATASET // FICTIONAL // LOCAL ONLY</span><span class="window-footer-status">READY</span></div>`; },
  bindWindow(el,appId){ el.addEventListener('pointerdown',()=>this.focus(appId)); el.addEventListener('click',event=>{ const action=event.target.closest('[data-window-action]')?.dataset.windowAction; if(!action)return; if(action==='close')this.close(appId); if(action==='minimize')this.minimize(appId); if(action==='maximize')this.maximize(appId); }); const bar=$('.window-titlebar',el); let drag=null; bar.addEventListener('pointerdown',event=>{ if(event.target.closest('button'))return; if(el.classList.contains('is-max'))return; drag={x:event.clientX,y:event.clientY,left:el.offsetLeft,top:el.offsetTop}; bar.setPointerCapture(event.pointerId); }); bar.addEventListener('pointermove',event=>{ if(!drag)return; const bounds=$('#window-layer').getBoundingClientRect(); const nextLeft=Math.max(0,Math.min(bounds.width-el.offsetWidth,drag.left+event.clientX-drag.x)); const nextTop=Math.max(0,Math.min(bounds.height-el.offsetHeight,drag.top+event.clientY-drag.y)); el.style.left=`${nextLeft}px`; el.style.top=`${nextTop}px`; }); bar.addEventListener('pointerup',()=>drag=null); },
  focus(appId){ const entry=this.windows.get(appId); if(!entry)return; entry.el.classList.remove('is-min'); entry.el.style.zIndex=++this.z; this.active=appId; $$('.app-launcher button').forEach(button=>button.classList.toggle('is-active',button.dataset.openApp===appId)); renderTaskbar(); },
  close(appId){ const entry=this.windows.get(appId); if(!entry)return; entry.el.remove(); this.windows.delete(appId); if(this.active===appId)this.active=null; renderTaskbar(); },
  minimize(appId){ const entry=this.windows.get(appId); if(!entry)return; entry.el.classList.add('is-min'); renderTaskbar(); },
  maximize(appId){ const entry=this.windows.get(appId); if(!entry)return; entry.maximized=!entry.maximized; entry.el.classList.toggle('is-max',entry.maximized); this.focus(appId); },
  refresh(appId){ const entry=this.windows.get(appId); if(entry) renderApp(appId); }
};

function markFlag(group, value){ S().flags[group] ||= []; addUnique(S().flags[group], value); StateStore.save(); }
function revealEvidence(id){ const item=getEvidence(id); if(!item)return; item.unlocked=true; addUnique(S().foundEvidence,id); const message=`Bukti ${item.title} tersedia di Evidence Board.`; NotificationManager.push('BUKTI TERBUKA',message); StateStore.save(); }
function markMissionTask(task){ if(!task.check(S())) return false; if(S().history.includes(task.id))return true; addUnique(S().history,task.id); NotificationManager.push('TUGAS SELESAI',task.label); AudioManager.success(); StateStore.save(); return true; }
function missionProgress(mission=currentMission()){ const done=mission.tasks?.filter(task=>task.check(S())).length || 0; return {done,total:mission.tasks?.length||0,percent:mission.tasks?.length?Math.round(done/mission.tasks.length*100):0}; }
function missionComplete(mission){ return Boolean(mission.tasks?.length && missionProgress(mission).done===mission.tasks.length); }
function submitMission(){ const mission=currentMission(); if(!missionComplete(mission)){ NotificationManager.push('LAPORAN DITAHAN','Selesaikan seluruh tugas investigasi sebelum mengirim laporan.','warn'); AudioManager.alert(); return; } if(S().completedMissions.includes(mission.id)){ NotificationManager.push('KASUS TERSIMPAN','Laporan untuk misi ini sudah tercatat.'); return; } S().completedMissions.push(mission.id); S().xp+=mission.xp; if(mission.id<missionDefs.length) S().currentMission=mission.id+1; StateStore.save('CASE GRADED'); renderAll(); NotificationManager.push('LAPORAN DITERIMA',`Misi ${String(mission.id).padStart(2,'0')} selesai. +${mission.xp} XP.`); DialogueEngine.show([{speaker:'Operations Control',color:'var(--green)',text:`Laporan ${mission.title} tercatat. Akses misi berikutnya dibuka. Jangan lepaskan hubungan yang sudah terbukti.`}],()=>{ WindowManager.open('case-files'); }); }

function renderLauncher(){ $('#app-launcher').innerHTML=APP_REGISTRY.map(app=>`<button data-open-app="${app.id}" title="Buka ${esc(app.label)}"><span class="app-glyph">${esc(app.glyph)}</span><span class="app-label">${esc(app.label.split(' ')[0])}</span></button>`).join(''); }
function renderDesktop(){ const mission=currentMission(), p=missionProgress(mission), rank=rankNames[rankFor(S().xp)]; $('#agent-greeting').textContent=(S().agentName||'AGENT').toUpperCase(); $('#rail-avatar').textContent=(S().agentName||'AG').slice(0,2).toUpperCase(); $('#rail-level').textContent=`R${String(rankFor(S().xp)+1).padStart(2,'0')}`; $('#desktop-overview').innerHTML=`<div class="overview-card primary"><p class="eyebrow">CASE IN PROGRESS // ${String(mission.id).padStart(2,'0')}</p><h3>${esc(mission.title)}</h3><p>${esc(mission.summary)}</p></div><div class="overview-card"><span class="stat-value">${p.percent}%</span><span class="stat-label">CASE PROGRESS</span></div><div class="overview-card"><span class="stat-value">${S().foundEvidence.length}</span><span class="stat-label">EVIDENCE LOGGED</span></div><div class="overview-card"><span class="stat-value">${S().xp}</span><span class="stat-label">TOTAL XP</span></div>`; $('#taskbar-xp').textContent=`XP ${String(S().xp).padStart(4,'0')} // ${rank}`; document.body.classList.toggle('low-motion', Boolean(S().settings.lowMotion)); document.documentElement.style.setProperty('--text-scale', `${S().settings.textSize||100}%`); }
function renderMissionDock(){ const mission=currentMission(), p=missionProgress(mission), open=missionComplete(mission); $('#mission-dock').innerHTML=`<div class="mission-dock-main"><div class="mission-dock-title"><span>${esc(mission.act)}</span><strong>M${String(mission.id).padStart(2,'0')} // ${esc(mission.title)}</strong></div><div class="mission-progress"><div class="progress-track"><span style="width:${p.percent}%"></span></div><span class="progress-label">${p.done}/${p.total||'—'} TUGAS</span></div></div><div class="dock-side"><div><span class="stat-value">${S().foundEvidence.length}</span><span class="stat-label">EVIDENCE</span></div><button class="btn ${open?'btn-primary':'btn-ghost'} btn-small" data-open-app="case-files">${open?'KIRIM LAPORAN':'LIHAT KASUS'}</button></div>`; }
function renderTaskbar(){ const items=[...WindowManager.windows.entries()]; $('#taskbar-windows').innerHTML=items.map(([id,entry])=>{ const app=APP_REGISTRY.find(x=>x.id===id); return `<button class="taskbar-window ${WindowManager.active===id?'is-active':''}" data-taskbar-app="${id}">${esc(app.label)}</button>`; }).join(''); }
function renderAll(){ renderDesktop(); renderMissionDock(); renderLauncher(); WindowManager.windows.forEach((_,id)=>renderApp(id)); }

function setSelectedHuman(id){ S().ui.selectedHuman=id; markFlag('viewedHuman',id); StateStore.save(); WindowManager.refresh('human-db'); }
function setSelectedVehicle(id){ S().ui.selectedVehicle=id; markFlag('viewedVehicle',id); StateStore.save(); WindowManager.refresh('vehicle-db'); }
function renderApp(appId){ const entry=WindowManager.windows.get(appId); if(!entry)return; const content=$('.window-content',entry.el); const views={'human-db':renderHumanDB,'vehicle-db':renderVehicleDB,'case-files':renderCaseFiles,'forensic-lab':renderForensicLab,'face-analysis':renderFaceAnalysis,'plate-reader':renderPlateReader,'cctv-archive':renderCCTV,'communications':renderCommunications,'secure-mail':renderMail,'server-control':renderServer,'intel-map':renderMap,'evidence-board':renderBoard,'terminal':renderTerminal,'profile':renderProfile,'settings':renderSettings}; content.innerHTML=(views[appId]||renderPlaceholder)(); bindAppContent(content,appId); }
function renderPlaceholder(){ return `<div class="empty-state"><p class="eyebrow">MODULE READY</p><p>Modul ini terdaftar dalam workstation CIB dan menunggu dataset kasus berikutnya.</p></div>`; }
function appHeader(kicker,title,copy){ return `<div class="section-head"><div><p class="eyebrow">${esc(kicker)}</p><h3>${esc(title)}</h3>${copy?`<p>${esc(copy)}</p>`:''}</div></div>`; }
function humanRow(item){ return `<button class="data-row" data-human="${item.id}"><span class="data-row-icon">H</span><span class="data-row-main"><strong>${esc(item.name)}</strong><small>${esc(item.id)} // ${esc(item.alias)} // ${esc(item.job)}</small></span><span class="data-row-side"><span class="tag ${item.status==='SUSPECT'?'red':item.status==='AGENT'?'green':'cyan'}">${esc(item.status)}</span></span></button>`; }
function renderHumanDB(){ const selected=getHuman(S().ui.selectedHuman); const query=(S().ui.humanQuery||'').toLowerCase(); const filter=S().ui.humanFilter||'ALL'; const results=humans.filter(item=>(filter==='ALL'||item.status===filter) && [item.id,item.name,item.alias,item.job,item.note].join(' ').toLowerCase().includes(query)); if(selected){ return `${appHeader('IDENTITY INDEX // PROFILE',selected.name,`${selected.id} // DATA CONFIDENCE ${selected.trust}`)}<div class="profile-layout"><div><div class="profile-portrait" data-lightbox="${selected.id}"><span class="portrait-id">${selected.id}</span></div><button class="btn btn-ghost btn-wide btn-small" data-action="back-human">← KEMBALI KE INDEX</button></div><div><div class="detail-grid"><div class="detail-item"><label>ALIAS</label><strong>${esc(selected.alias)}</strong></div><div class="detail-item"><label>STATUS</label><strong>${esc(selected.status)}</strong></div><div class="detail-item"><label>TANGGAL LAHIR</label><strong>${esc(selected.birth)} // ${selected.age} TAHUN</strong></div><div class="detail-item"><label>GENDER</label><strong>${esc(selected.gender)}</strong></div><div class="detail-item"><label>LATAR</label><strong>${esc(selected.origin)}</strong></div><div class="detail-item"><label>PEKERJAAN</label><strong>${esc(selected.job)}</strong></div><div class="detail-item detail-wide"><label>CATATAN INVESTIGASI</label><strong>${esc(selected.note)}</strong></div><div class="detail-item detail-wide"><label>RIWAYAT MUNCUL</label><strong>${esc(selected.missions)}</strong></div></div><div class="relationship-list">${selected.links.map(link=>`<button class="tag cyan" data-related="${link}">${esc(link)}</button>`).join('')}</div></div></div>`; } return `${appHeader('HUMAN DB // IDENTITY INDEX','Cari profil manusia','Dataset fiktif terkurasi. Hasil tidak dibuat secara acak.') }<form class="search-row" data-form="human-search"><input class="search-input" name="query" value="${esc(S().ui.humanQuery||'')}" placeholder="Nama, alias, ID, kata kunci..." autocomplete="off"><button class="btn btn-primary" type="submit">CARI</button></form><div class="filter-row">${['ALL','AGENT','WITNESS','PERSON OF INTEREST','SUSPECT','OFFICIAL'].map(f=>`<button class="filter-chip ${(filter===f)?'is-active':''}" data-human-filter="${f}">${f}</button>`).join('')}</div><div class="data-list">${results.length?results.slice(0,12).map(humanRow).join(''):`<div class="empty-state">Tidak ada profil yang cocok dengan parameter ini.</div>`}</div><div class="window-footer-status" style="margin-top:13px;color:var(--faint);font:9px var(--font-display);letter-spacing:.1em">${results.length} RECORD TERSEDIA // SEARCH HISTORY ${S().searchHistory.filter(x=>x.type==='human').length}</div>`; }
function vehicleRow(item){ return `<button class="data-row" data-vehicle="${item.id}"><span class="data-row-icon">V</span><span class="data-row-main"><strong>${esc(item.plate)} // ${esc(item.make)} ${esc(item.model)}</strong><small>${esc(item.id)} // ${esc(item.color)} // ${esc(item.type)}</small></span><span class="data-row-side"><span class="tag ${item.status==='DICARI'?'red':item.status==='AKTIF'?'green':'amber'}">${esc(item.status)}</span></span></button>`; }
function renderVehicleDB(){ const selected=getVehicle(S().ui.selectedVehicle); const query=(S().ui.vehicleQuery||'').toLowerCase(); const filter=S().ui.vehicleFilter||'ALL'; const results=vehicles.filter(item=>(filter==='ALL'||item.color===filter) && [item.id,item.plate,item.make,item.model,item.color,item.owner].join(' ').toLowerCase().includes(query)); if(selected){ const owner=getHuman(selected.owner); return `${appHeader('VEHICLE DB // REGISTRY',`${selected.make} ${selected.model}`,`${selected.id} // ${selected.plate} // ${selected.status}`)}<div class="profile-layout"><div><div class="profile-portrait" style="background:radial-gradient(circle at 50% 44%,rgba(255,200,87,.22),transparent 28%),linear-gradient(145deg,#332d1d,#0b0e0e)" data-lightbox="${selected.id}"><span class="portrait-id">${selected.plate}</span></div><button class="btn btn-ghost btn-wide btn-small" data-action="back-vehicle">← KEMBALI KE REGISTRY</button></div><div><div class="detail-grid"><div class="detail-item"><label>MAKE / MODEL</label><strong>${esc(selected.make)} ${esc(selected.model)}</strong></div><div class="detail-item"><label>TAHUN</label><strong>${selected.year}</strong></div><div class="detail-item"><label>WARNA / TIPE</label><strong>${esc(selected.color)} // ${esc(selected.type)}</strong></div><div class="detail-item"><label>PLAT</label><strong>${esc(selected.plate)}</strong></div><div class="detail-item"><label>PEMILIK TERDAFTAR</label><strong>${owner?esc(owner.name):'UNKNOWN'} // ${esc(selected.owner)}</strong></div><div class="detail-item"><label>STATUS</label><strong>${esc(selected.status)}</strong></div><div class="detail-item detail-wide"><label>LOKASI TERAKHIR</label><strong>${esc(selected.last)}</strong></div><div class="detail-item detail-wide"><label>CATATAN</label><strong>${esc(selected.note)}</strong></div></div><div class="relationship-list"><button class="tag cyan" data-human="${selected.owner}">OPEN ${esc(selected.owner)}</button>${selected.links.map(link=>`<button class="tag amber" data-related="${link}">${esc(link)}</button>`).join('')}</div></div></div>`; } return `${appHeader('VEHICLE DB // REGISTRY','Cari kendaraan','Pelat, model, pemilik dan riwayat kemunculan tersimpan konsisten.') }<form class="search-row" data-form="vehicle-search"><input class="search-input" name="query" value="${esc(S().ui.vehicleQuery||'')}" placeholder="Nomor pelat, model, ID..." autocomplete="off"><button class="btn btn-primary" type="submit">CARI</button></form><div class="filter-row">${['ALL','Hitam','Putih','Abu-abu','Biru tua','Perak','Merah marun'].map(f=>`<button class="filter-chip ${(filter===f)?'is-active':''}" data-vehicle-filter="${f}">${f}</button>`).join('')}</div><div class="data-list">${results.length?results.slice(0,12).map(vehicleRow).join(''):`<div class="empty-state">Tidak ada kendaraan yang cocok.</div>`}</div>`; }
function caseCard(mission){ const unlocked=isUnlocked(mission); const p=missionProgress(mission); return `<button class="data-row ${unlocked?'':'is-locked'}" data-mission="${mission.id}" ${unlocked?'':'disabled'}><span class="data-row-icon">${unlocked?String(mission.id).padStart(2,'0'):'—'}</span><span class="data-row-main"><strong>M${String(mission.id).padStart(2,'0')} // ${esc(mission.title)}</strong><small>${esc(mission.act)} // ${unlocked?esc(mission.summary):'CLEARANCE TERKUNCI'}</small></span><span class="data-row-side">${unlocked?`<span class="tag ${S().completedMissions.includes(mission.id)?'green':'cyan'}">${S().completedMissions.includes(mission.id)?'CLOSED':`${p.percent}%`}</span>`:'<span class="tag">LOCKED</span>'}</span></button>`; }
function renderCaseFiles(){ const mission=S().ui.selectedMission?missionDefs.find(m=>m.id===S().ui.selectedMission):currentMission(); const p=missionProgress(mission); const tasks=mission.tasks||[]; return `${appHeader('CASE FILES // CAMPAIGN CONTROL','Manajemen kasus','Tepat 20 misi utama. Setiap tugas membaca state investigasi yang sama.')}<div class="case-summary"><div><span class="case-id">${mission.caseId} // MISSION ${String(mission.id).padStart(2,'0')}</span><h3>${esc(mission.title)}</h3><p>${esc(mission.briefing)}</p></div><div class="case-priority"><span class="tag ${mission.priority==='CRITICAL'?'red':mission.priority==='HIGH'?'amber':'cyan'}">${mission.priority}</span><p style="margin-top:8px;color:var(--muted);font:10px ui-monospace">${p.done}/${p.total||0} TASKS</p></div></div><div class="section-head"><div><p class="eyebrow">ACTIVE TASKS</p><h4>Daftar tugas investigasi</h4></div>${mission.id>4?'<span class="tag amber">ROADMAP DATA</span>':''}</div><div class="task-list">${tasks.length?tasks.map(task=>{ const done=task.check(S()); return `<div class="task-row ${done?'is-done':''}"><span class="task-check"></span><div><strong>${esc(task.label)}</strong><small>${esc(task.hint)}</small></div></div>`; }).join(''):`<div class="empty-state">Misi ini memiliki brief dan kontrak data yang siap diisi pada fase kampanye berikutnya.</div>`}</div><div class="case-footer"><span class="muted">Evidence yang ditemukan: ${S().foundEvidence.length}</span>${mission.id===S().currentMission&&tasks.length?`<button class="btn ${missionComplete(mission)?'btn-primary':'btn-ghost'}" data-action="submit-mission">${missionComplete(mission)?'KIRIM LAPORAN':'LAPORAN'}</button>`:''}</div><div style="height:1px;background:var(--line);margin:18px 0"></div><div class="section-head"><div><p class="eyebrow">CAMPAIGN INDEX</p><h4>20 Misi utama</h4></div><span class="muted" style="font-size:10px">${S().completedMissions.length}/20 CLOSED</span></div><div class="data-list">${missionDefs.map(caseCard).join('')}</div>`; }
function renderForensicLab(){ const found=evidence.filter(item=>S().foundEvidence.includes(item.id)); const selected=getEvidence(S().ui.selectedEvidence)||found[0]; if(!selected)return `${appHeader('FORENSIC LAB','Laboratorium bukti','Belum ada bukti yang dapat dianalisis.')}<div class="empty-state">Buka email dan aplikasi investigasi untuk mengumpulkan bukti pertama.</div>`; const analyzed=S().flags.forensic?.includes(selected.id); return `${appHeader('FORENSIC LAB // EVIDENCE DESK',selected.title,'Hasil analisis berasal dari data fiktif yang sudah ditanamkan, bukan AI sungguhan.')}<div class="profile-layout"><div><div class="evidence-preview"><span class="portrait-id">${selected.id} // ${selected.type}</span><strong style="font:700 28px var(--font-display);color:var(--cyan)">${selected.type.slice(0,3)}</strong></div><button class="btn btn-primary btn-wide btn-small" data-action="analyze-evidence">${analyzed?'ANALISIS TERSIMPAN':'ANALISIS BUKTI'}</button></div><div><div class="callout ${analyzed?'':'warn'}"><strong>${analyzed?'HASIL TERSEDIA':'STATUS MENUNGGU ANALISIS'}</strong><br>${analyzed?esc(selected.summary):'Jalankan pemeriksaan untuk membuka temuan deterministik.'}</div><div class="detail-grid" style="margin-top:15px"><div class="detail-item"><label>SUMBER</label><strong>${esc(selected.source)}</strong></div><div class="detail-item"><label>TAG KASUS</label><strong>${esc(selected.tags.join(' // '))}</strong></div><div class="detail-item detail-wide"><label>CATATAN METODE</label><strong>${analyzed?'Pembacaan lokal membandingkan metadata yang sudah tersedia dalam dataset.':'Tidak ada koneksi eksternal atau pemindaian sistem nyata.'}</strong></div></div></div></div><div style="height:1px;background:var(--line);margin:18px 0"></div><div class="section-head"><div><p class="eyebrow">EVIDENCE INVENTORY</p><h4>Bukti terbuka</h4></div><span class="muted" style="font-size:10px">${found.length} ITEM</span></div><div class="evidence-grid">${found.map(item=>`<div class="evidence-card ${item.id===selected.id?'is-found':''}"><div class="evidence-art">${esc(item.type.slice(0,3))}</div><div class="evidence-body"><strong>${esc(item.title)}</strong><small>${esc(item.summary)}</small><button class="btn btn-ghost btn-small btn-wide" data-evidence-inspect="${item.id}">PERIKSA</button></div></div>`).join('')}</div>`; }
function renderFaceAnalysis(){ const ready=S().foundEvidence.includes('EVD-014'); const analyzed=Boolean(S().flags.faceAnalysis); return `${appHeader('FACE ANALYSIS // SIMULATION','Analisis wajah','Pencocokan memakai hasil yang sudah ditentukan untuk bukti fiktif.')}<div class="profile-layout"><div><div class="evidence-preview" style="background:radial-gradient(circle at 55% 42%,rgba(255,94,104,.2),transparent 25%),linear-gradient(145deg,#2c1a21,#090d10)"><span class="portrait-id">EVD-014 // FRAME</span><strong style="font:700 28px var(--font-display);color:var(--red)">FACE</strong></div><button class="btn ${ready?'btn-primary':'btn-ghost'} btn-wide" data-action="run-face" ${ready?'':'disabled'}>${analyzed?'ULANGI ANALISIS':'JALANKAN SCAN'}</button></div><div><div class="callout ${ready?'':'warn'}"><strong>${ready?'INPUT READY':'INPUT TERKUNCI'}</strong><br>${ready?'Frame EVD-014 sudah tersedia. Hasil akan tetap memiliki kemungkinan kesalahan.':'Bukti wajah muncul setelah kasus adegan terbuka pada fase kampanye.'}</div>${analyzed?`<div class="detail-grid" style="margin-top:15px"><div class="detail-item"><label>KANDIDAT TERATAS</label><strong>Tara Kusuma // HUM-010</strong></div><div class="detail-item"><label>KEMIRIPAN</label><strong style="color:var(--amber)">78% // SIMULASI</strong></div><div class="detail-item detail-wide"><label>PENJELASAN</label><strong>Kontur wajah dan sudut rahang cocok sebagian. Wajah tertutup bayangan; hasil tidak cukup untuk identifikasi tunggal.</strong></div></div>`:'<div class="empty-state" style="margin-top:15px">Hasil kandidat akan muncul setelah pemindaian dijalankan.</div>'}</div></div>`; }
function renderPlateReader(){ const ready=Boolean(S().flags.cctvSnapshot); const decoded=S().flags.plateRead==='BXR-2041'; return `${appHeader('PLATE READER // FRAME DECODER','Pembacaan pelat','Decoder ini hanya membaca frame CCTV fiktif yang sudah dikunci oleh game.')}<div class="cctv-screen" style="min-height:210px;background:linear-gradient(140deg,#171d1d,#0a0f11)"><div class="cctv-frame" style="inset:31% 28% 25% 29%"></div><div class="cctv-subject" style="left:47%;bottom:25%;width:84px;height:42px;clip-path:none;background:linear-gradient(90deg,#0b1012 0 20%,#242f32 20% 80%,#0b1012 80%);border-color:rgba(255,200,87,.6)"></div><span class="cctv-hud">FRAME // 23:41:06</span><span class="cctv-time">${decoded?'BXR-2041':'PLATE UNKNOWN'}</span><span class="cctv-caption">CAM-02 // NORTHERN ACCESS</span></div><div class="callout ${ready?'':'warn'}" style="margin-top:14px"><strong>${ready?'FRAME TERKUNCI':'MENUNGGU SNAPSHOT'}</strong><br>${ready?'Kamera memberi cukup detail untuk pembacaan simulasi.':'Ambil snapshot dari CCTV ARCHIVE sebelum menjalankan decoder.'}</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:14px;gap:10px"><div>${decoded?'<span class="tag green">BXR-2041 // CONFIDENCE 96%</span>':'<span class="tag">NO RESULT</span>'}</div><button class="btn ${ready?'btn-primary':'btn-ghost'}" data-action="read-plate" ${ready?'':'disabled'}>${decoded?'BANDINGKAN KE VEHICLE DB':'BACA FRAME'}</button></div>${decoded?'<div class="relationship-list" style="margin-top:16px"><button class="tag amber" data-vehicle="VEH-001">OPEN VEH-001</button><button class="tag cyan" data-action="add-evidence" data-evidence="EVD-010">TAMBAHKAN KE BOARD</button></div>':''}`; }
function renderCCTV(){ const playing=Boolean(S().flags.cctvPlaying); const snapshot=Boolean(S().flags.cctvSnapshot); return `${appHeader('CCTV ARCHIVE // CAM-02','Kamera Utara','Rekaman visual fiktif dengan timeline dan marker kejadian.')}<div class="cctv-screen"><div class="cctv-frame"></div><div class="cctv-subject"></div><span class="cctv-hud">CAM-02 // NORTHERN ACCESS</span><span class="cctv-time">23:41:${playing?'06':'00'}</span><span class="cctv-caption">${snapshot?'SNAPSHOT LOCKED // PLATE REGION':'MOTION TRACK // 1 SUBJECT DETECTED'}</span></div><div class="timeline"><div class="timeline-track"></div><span class="timeline-marker" style="left:74%"></span></div><div class="media-controls"><button class="btn btn-small" data-action="toggle-cctv">${playing?'PAUSE':'PLAY'}</button><button class="btn btn-small ${snapshot?'btn-primary':''}" data-action="cctv-snapshot">${snapshot?'SNAPSHOT TERSIMPAN':'AMBIL SNAPSHOT'}</button><span class="timecode">00:00:00 / 00:02:14</span></div><div class="callout" style="margin-top:15px"><strong>MARKER // 23:41:06</strong><br>Bayangan kendaraan melintas dari timur ke utara. Frame target dapat dipakai oleh PLATE READER.</div>`; }
function renderCommunications(){ const selected=calls.find(c=>c.id===S().ui.selectedCall); return `${appHeader('COMMUNICATIONS // CIB LINES','Pusat komunikasi','Panggilan penting menyimpan konteks dan memengaruhi progres kasus.')}<div class="mail-layout" style="min-height:300px"><div class="mail-list"><div class="mail-list-tabs"><button class="mail-tab is-active">HISTORY</button></div>${calls.slice(0,8).map(call=>`<button class="mail-row ${call.id===S().ui.selectedCall?'is-active':''}" data-call="${call.id}"><strong>${esc(call.name)}</strong><span>${esc(call.type)} // ${esc(call.time)}</span></button>`).join('')}</div><div class="mail-detail">${selected?`<p class="eyebrow">${esc(selected.type)} // ${esc(selected.time)}</p><h3>${esc(selected.name)}</h3><div class="mail-meta"><span>${esc(selected.summary)}</span><span>${selected.lines.length} LINES</span></div><div class="mail-body">${selected.lines.map(line=>`<p style="margin-bottom:10px">${esc(line)}</p>`).join('')}</div><button class="btn ${selected.id==='C-003'?'btn-primary':'btn-ghost'}" data-action="start-call" data-call="${selected.id}">${selected.id==='C-003'?'HUBUNGI MAYA':'PUTAR ULANG'}</button>`:'<div class="empty-state">Pilih riwayat panggilan.</div>'}</div></div>`; }
function renderMail(){ const available=mail.filter(item=>item.mission<=S().currentMission || S().completedMissions.includes(item.mission)); const selected=getMail(S().ui.selectedMail)||available[0]; return `${appHeader('SECURE MAIL // INBOX','Kotak surat internal','Pesan berubah mengikuti perkembangan kasus. Lampiran tetap fiktif dan lokal.')}<div class="mail-layout"><div class="mail-list"><div class="mail-list-tabs"><button class="mail-tab is-active">INBOX</button><button class="mail-tab">ARCHIVE</button></div>${available.map(item=>`<button class="mail-row ${item.id===S().ui.selectedMail?'is-active':''} ${S().readMail.includes(item.id)?'':'unread'}" data-mail="${item.id}"><strong>${esc(item.subject)}</strong><span>${esc(item.from)} // ${esc(item.time)}</span></button>`).join('')}</div><div class="mail-detail">${selected?`<p class="eyebrow">${esc(selected.role)} // ${esc(selected.time)}</p><h3>${esc(selected.subject)}</h3><div class="mail-meta"><span>${esc(selected.from)}</span><span>${S().readMail.includes(selected.id)?'READ':'UNREAD'}</span></div><div class="mail-body">${esc(selected.body)}</div><div class="attachment-row">${selected.attachments.map(id=>`<button class="attachment" data-evidence-inspect="${id}">ATTACHMENT // ${id}</button>`).join('')}</div>`:'<div class="empty-state">Tidak ada mail pada clearance ini.</div>'}</div></div>`; }
function renderServer(){ const checked=Boolean(S().flags.serverChecked); const cpu=48+Math.floor((Date.now()/1700)%20), mem=61+Math.floor((Date.now()/2300)%12); return `${appHeader('SERVER CONTROL // LOCAL NODE','Kontrol server','Semua status adalah simulasi lokal. Tidak ada scanning ke jaringan nyata.')}<div class="server-layout"><div><div class="server-visual"><div class="server-rack">${Array.from({length:5},(_,i)=>`<div class="rack-unit"><span class="rack-leds"><i></i><i></i><i></i></span><span style="font:9px var(--font-display);color:var(--muted)">CIB-NODE-${String(i+1).padStart(2,'0')}</span></div>`).join('')}</div><div class="server-readout"><div class="readout"><label>CPU LOAD</label><strong>${cpu}%</strong></div><div class="readout"><label>MEMORY</label><strong>${mem}%</strong></div><div class="readout"><label>UPTIME</label><strong>19:44:08</strong></div></div></div><button class="btn ${checked?'btn-primary':'btn-ghost'}" style="margin-top:12px" data-action="server-diagnostic">${checked?'DIAGNOSTIC TERCATAT':'JALANKAN DIAGNOSTIC'}</button></div><div><div class="callout ${checked?'':'warn'}"><strong>${checked?'NODE STATUS // STABLE':'ALERT // DIAGNOSTIC REQUIRED'}</strong><br>${checked?'Riwayat aktivitas lokal sudah dicatat untuk kasus berikutnya.':'Terdapat anomali pada status backup simulasi. Buka log untuk menandai temuan.'}</div><div class="data-list" style="margin-top:12px"><div class="data-row"><span class="data-row-icon">DB</span><span class="data-row-main"><strong>CASE DATABASE</strong><small>SYNC // LOCAL</small></span><span class="tag green">ONLINE</span></div><div class="data-row"><span class="data-row-icon">BK</span><span class="data-row-main"><strong>BACKUP MIRROR</strong><small>LAST CHECK // 02:09</small></span><span class="tag ${checked?'green':'red'}">${checked?'VERIFIED':'REVIEW'}</span></div></div></div></div>`; }
function renderMap(){ const active=S().ui.activeMap||'LOC-001'; return `${appHeader('INTEL MAP // SCHEMATIC','Peta investigasi','Lokasi fiktif, hubungan jalur dan marker kejadian.')}<div class="map-layout"><div class="map-screen">${locations.slice(1,6).map((loc,i)=>`<span class="map-line" style="left:${locations[0].x}%;top:${locations[0].y}%;width:${Math.hypot(loc.x-locations[0].x,loc.y-locations[0].y)}%;transform:rotate(${Math.atan2(loc.y-locations[0].y,loc.x-locations[0].x)*180/Math.PI}deg)"></span>`).join('')}${locations.map(loc=>`<button class="map-marker ${active===loc.id?'is-active':''}" style="left:${loc.x}%;top:${loc.y}%" data-map-location="${loc.id}" title="${esc(loc.name)}"><span class="map-marker-label">${esc(loc.name)}</span></button>`).join('')}<span class="map-coords">GRID // 07-ARUNIKA // SIMULATION</span></div><div class="map-list">${locations.map(loc=>`<button class="map-location ${active===loc.id?'is-active':''}" data-map-location="${loc.id}"><strong>${esc(loc.name)}</strong><small>${esc(loc.type)} // ${esc(loc.note)}</small></button>`).join('')}</div></div>`; }
function renderBoard(){ const board=evidence.filter(item=>S().boardItems.includes(item.id)); const available=evidence.filter(item=>S().foundEvidence.includes(item.id)&&!S().boardItems.includes(item.id)); return `${appHeader('EVIDENCE BOARD // RELATION MAP','Papan hubungan bukti','Tambahkan kartu lalu pilih HUBUNGKAN untuk membuat relasi investigasi.')}<div class="board">${board.map((item,i)=>{ const pos=S().ui.boardPositions?.[item.id]||{x:24+(i%3)*190,y:48+Math.floor(i/3)*110}; return `<div class="evidence-node" data-board-node="${item.id}" style="left:${pos.x}px;top:${pos.y}px"><strong>${esc(item.title)}</strong><small>${esc(item.id)} // ${esc(item.source)}</small></div>`; }).join('')}${S().boardLinks.map(link=>`<div class="board-link" data-link="${link.from}-${link.to}"></div>`).join('')}</div><div class="board-legend"><span><i class="legend-dot"></i>VERIFIED CARD</span><span><i class="legend-dot amber"></i>LINK ${S().boardLinks.length}</span><span class="muted">${S().ui.linkStart?`Pilih kartu kedua untuk menghubungkan ${S().ui.linkStart}`:'Geser kartu untuk mengatur susunan.'}</span></div><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:13px">${available.length?available.map(item=>`<button class="btn btn-ghost btn-small" data-action="add-evidence" data-evidence="${item.id}">+ ${esc(item.title)}</button>`).join(''):'<span class="muted" style="font-size:10px">Semua bukti terbuka sudah berada di board.</span>'}</div>`; }
function renderTerminal(){ return `${appHeader('TERMINAL // SAFE PARSER','CIB Terminal','Perintah diproses oleh parser game. Tidak ada shell atau command OS yang dijalankan.')}<div class="terminal">${S().terminalLog.map(line=>`<div class="terminal-line ${line.kind||''}">${esc(line.text)}</div>`).join('')}<form class="terminal-form" data-form="terminal"><span class="terminal-prompt">CIB&gt;</span><input class="terminal-input" name="command" autocomplete="off" placeholder="help"><button class="btn btn-small btn-primary" type="submit">RUN</button></form></div>`; }
function renderProfile(){ const rank=rankNames[rankFor(S().xp)], next=(rankFor(S().xp)+1<rankNames.length?500*(rankFor(S().xp)+1):'MAX'); return `${appHeader('AGENT PROFILE // PERSONNEL','Profil agen','Riwayat operasi dan statistik lokal.')}<div class="profile-layout"><div><div class="profile-portrait" style="background:radial-gradient(circle at 50% 38%,rgba(255,200,87,.2),transparent 29%),linear-gradient(145deg,#2b2517,#080e12)"><span class="portrait-id">AGENT // ${(S().agentName||'NEW').slice(0,8).toUpperCase()}</span></div><div class="callout" style="margin-top:9px"><strong>${esc(rank)}</strong><br>Clearance ${rankFor(S().xp)+1} // ${S().xp}/${next} XP</div></div><div><div class="detail-grid"><div class="detail-item"><label>NAMA OPERASIONAL</label><strong>${esc(S().agentName||'UNASSIGNED')}</strong></div><div class="detail-item"><label>AGENT ID</label><strong>CIB-07-${String((S().agentName||'AG').length).padStart(2,'0')}</strong></div><div class="detail-item"><label>KASUS SELESAI</label><strong>${S().completedMissions.length} / 20</strong></div><div class="detail-item"><label>BUKTI TERCATAT</label><strong>${S().foundEvidence.length} / ${evidence.length}</strong></div><div class="detail-item detail-wide"><label>ACHIEVEMENT</label><strong>${S().completedMissions.length>=1?'FIRST SIGNAL // ':''}${S().foundEvidence.length>=8?'EVIDENCE BUILDER // ':''}${S().completedMissions.length>=4?'MIDNIGHT TRACE':''||'RECRUIT INTAKE'}</strong></div></div><label class="eyebrow" style="display:block;margin-top:18px">CATATAN INVESTIGASI</label><textarea class="note-input" id="agent-notes" rows="5" placeholder="Tulis catatan yang ingin disimpan...">${esc(S().notes)}</textarea><button class="btn btn-primary" style="margin-top:8px" data-action="save-note">SIMPAN CATATAN</button></div></div>`; }
function renderSettings(){ const settings=S().settings; const setting=(key,title,copy)=>`<div class="setting-row"><div><strong>${title}</strong><small>${copy}</small></div><label class="toggle"><input type="checkbox" data-setting="${key}" ${settings[key]?'checked':''}><span></span></label></div>`; return `${appHeader('SETTINGS // SYSTEM PREFS','Pengaturan workstation','Perubahan disimpan lokal dan dapat diubah kapan saja.')}<div class="settings-grid">${setting('master','MASTER FEEDBACK','Klik, notifikasi dan feedback Web Audio setelah interaksi pertama.')}${setting('voice','AGENT VOICE','Gunakan Web Speech API jika browser mendukung.')}${setting('subtitles','SUBTITLE','Tampilkan dialog dan narasi teks.')}${setting('lowMotion','LOW-MOTION MODE','Kurangi animasi untuk perangkat berkinerja rendah.')}</div><div style="margin-top:22px;padding-top:17px;border-top:1px solid var(--line)"><p class="eyebrow">DANGER ZONE</p><button class="btn btn-danger" data-action="open-reset">RESET LOCAL PROGRESS</button></div>`; }

function openMail(id){ const item=getMail(id); if(!item)return; S().ui.selectedMail=id; addUnique(S().readMail,id); item.attachments.forEach(evd=>{ if(['MSG-002','MSG-003','MSG-004'].includes(id)) revealEvidence(evd); }); if(id==='MSG-002') revealEvidence('EVD-004'); StateStore.save(); WindowManager.refresh('secure-mail'); renderMissionDock(); }
function runTerminal(raw){ const command=raw.trim(); if(!command)return; const log=S().terminalLog; log.push({text:`CIB> ${command}`,kind:'cmd'}); const lower=command.toLowerCase(); const parts=lower.split(/\s+/); const arg=command.split(/\s+/).slice(2).join(' ').trim(); if(lower==='help'){log.push({text:'help | status | cases | mail | evidence | search human [nama] | search vehicle [pelat] | open case [ID] | clear',kind:'ok'});} else if(lower==='status'){log.push({text:`NODE LOCAL // ${currentMission().caseId} // ${rankNames[rankFor(S().xp)]} // XP ${S().xp}`,kind:'ok'}); markFlag('terminal','status');} else if(lower==='cases'){log.push({text:missionDefs.filter(isUnlocked).map(m=>`M${String(m.id).padStart(2,'0')} ${m.title}`).join(' | '),kind:'ok'});} else if(lower==='mail'){log.push({text:`INBOX // ${mail.filter(m=>m.mission<=S().currentMission&&!S().readMail.includes(m.id)).length} UNREAD`,kind:'ok'});} else if(lower==='evidence'){log.push({text:`EVIDENCE // ${S().foundEvidence.join(', ')}`,kind:'ok'});} else if(parts[0]==='search'&&parts[1]==='human'&&arg){ S().ui.humanQuery=arg; S().searchHistory.push({type:'human',query:arg,time:Date.now()}); StateStore.save(); WindowManager.open('human-db'); log.push({text:`SEARCH HUMAN // ${arg}`,kind:'ok'});} else if(parts[0]==='search'&&parts[1]==='vehicle'&&arg){ S().ui.vehicleQuery=arg; S().searchHistory.push({type:'vehicle',query:arg,time:Date.now()}); StateStore.save(); WindowManager.open('vehicle-db'); log.push({text:`SEARCH VEHICLE // ${arg}`,kind:'ok'});} else if(parts[0]==='open'&&parts[1]==='case'){ const id=arg.toUpperCase(); const mission=missionDefs.find(m=>m.caseId===id); if(mission&&isUnlocked(mission)){S().ui.selectedMission=mission.id;WindowManager.open('case-files');log.push({text:`OPEN ${id} // ACCESS GRANTED`,kind:'ok'});}else log.push({text:`ACCESS DENIED // ${id||'CASE'}`,kind:'warn'});} else if(lower==='clear'){S().terminalLog=[];} else {log.push({text:'COMMAND NOT FOUND // ketik help untuk bantuan.',kind:'warn'});} S().terminalLog=log.slice(-18); StateStore.save(); WindowManager.refresh('terminal'); }
function bindAppContent(content){ content.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault(); const type=form.dataset.form; const formData=new FormData(form); if(type==='human-search'){ const query=String(formData.get('query')||''); S().ui.humanQuery=query; S().searchHistory.push({type:'human',query,time:Date.now()}); StateStore.save(); renderApp('human-db'); } if(type==='vehicle-search'){ const query=String(formData.get('query')||''); S().ui.vehicleQuery=query; S().searchHistory.push({type:'vehicle',query,time:Date.now()}); StateStore.save(); renderApp('vehicle-db'); } if(type==='terminal'){ runTerminal(String(formData.get('command')||'')); } })); }

function requestFullscreen(){ const root=document.documentElement; (root.requestFullscreen?.()||document.body.requestFullscreen?.())?.catch?.(()=>{}); screen.orientation?.lock?.('landscape').catch?.(()=>{}); }
function openLightbox(label){ $('#lightbox-content').innerHTML=`<div class="profile-portrait" style="width:min(520px,80vw);height:min(420px,70vh);display:grid;place-items:center"><strong style="font:700 48px var(--font-display);color:var(--cyan)">${esc(label)}</strong></div>`; $('#lightbox').classList.remove('is-hidden'); }
function showLogin(){ $('#boot-screen').classList.add('is-hidden'); $('#login-screen').classList.remove('is-hidden'); const input=$('#agent-name'); input.value=S().agentName||''; $('#login-message').textContent=S().agentName?'SAVE FOUND // AUTHENTICATE TO CONTINUE':'AUTHENTICATION REQUIRED // LOCAL SIMULATION'; input.focus(); }
function startBoot(){ $('#boot-screen').classList.remove('is-hidden'); $('#login-screen').classList.add('is-hidden'); $('#game-shell').classList.add('is-hidden'); const lines=['POWER BUS .............. OK','LOCAL CIPHER ........... READY','SIMULATION DATASET ..... 25 HUMANS / 15 VEHICLES','EVIDENCE INDEX .......... 40 ITEMS','CIB WORKSTATION ........ WAITING FOR AGENT']; let i=0; const log=$('#boot-log'), progress=$('#boot-progress'); window.clearInterval(window.bootTimer); window.bootTimer=window.setInterval(()=>{ if(i<lines.length){log.insertAdjacentHTML('beforeend',`<div>${lines[i]}</div>`);progress.style.width=`${Math.min(100,(i+1)*18)}%`;AudioManager.click();i++;} else {window.clearInterval(window.bootTimer);window.setTimeout(showLogin,320);}},270); }
function enterDesktop(){ S().loggedIn=true; StateStore.save('LOCAL SAVE'); $('#login-screen').classList.add('is-hidden'); $('#boot-screen').classList.add('is-hidden'); $('#game-shell').classList.remove('is-hidden'); renderAll(); if(!S().flags.onboarded){ S().flags.onboarded=true; StateStore.save(); window.setTimeout(()=>DialogueEngine.show([{speaker:'Agent Maya Pratama',color:'var(--cyan)',text:`Selamat datang di CIB, ${S().agentName}. Workstation ini bersifat lokal dan seluruh data di dalamnya fiktif.`},{speaker:'Agent Maya Pratama',color:'var(--cyan)',text:'Buka SECURE MAIL, baca memo saya, lalu periksa HUMAN DB. Setiap bukti yang kamu buka akan mengubah kasus yang sama.'},{speaker:'Agent Maya Pratama',color:'var(--cyan)',text:'Jangan kejar kecocokan. Kejar bukti yang bisa dipertanggungjawabkan.'}],()=>{WindowManager.open('secure-mail');}),400); } }

// Shell-level interactions: all controls are stateful and intentionally local to the simulation.
document.addEventListener('click',event=>{
  const open=event.target.closest('[data-open-app]'); if(open){ WindowManager.open(open.dataset.openApp); return; }
  const taskbar=event.target.closest('[data-taskbar-app]'); if(taskbar){ WindowManager.focus(taskbar.dataset.taskbarApp); return; }
  const human=event.target.closest('[data-human]'); if(human){ WindowManager.open('human-db'); setSelectedHuman(human.dataset.human); return; }
  const vehicle=event.target.closest('[data-vehicle]'); if(vehicle){ WindowManager.open('vehicle-db'); setSelectedVehicle(vehicle.dataset.vehicle); return; }
  const humanFilter=event.target.closest('[data-human-filter]'); if(humanFilter){S().ui.humanFilter=humanFilter.dataset.humanFilter;WindowManager.refresh('human-db');return;}
  const vehicleFilter=event.target.closest('[data-vehicle-filter]'); if(vehicleFilter){S().ui.vehicleFilter=vehicleFilter.dataset.vehicleFilter;WindowManager.refresh('vehicle-db');return;}
  const mission=event.target.closest('[data-mission]'); if(mission){ const item=missionDefs.find(m=>m.id===Number(mission.dataset.mission)); if(item&&isUnlocked(item)){S().ui.selectedMission=item.id;WindowManager.refresh('case-files');} return; }
  const mailButton=event.target.closest('[data-mail]'); if(mailButton){openMail(mailButton.dataset.mail);return;}
  const evidenceButton=event.target.closest('[data-evidence-inspect]'); if(evidenceButton){S().ui.selectedEvidence=evidenceButton.dataset.evidence;WindowManager.open('forensic-lab');WindowManager.refresh('forensic-lab');return;}
  const call=event.target.closest('[data-call]'); if(call){S().ui.selectedCall=call.dataset.call;WindowManager.refresh('communications');return;}
  const related=event.target.closest('[data-related]'); if(related){ const id=related.dataset.related; if(id.startsWith('HUM-')){WindowManager.open('human-db');setSelectedHuman(id);} else if(id.startsWith('VEH-')){WindowManager.open('vehicle-db');setSelectedVehicle(id);} else if(id.startsWith('CASE-')){const m=missionDefs.find(x=>x.caseId===id);if(m){WindowManager.open('case-files');S().ui.selectedMission=m.id;WindowManager.refresh('case-files');}} else if(id.startsWith('EVD-')){S().ui.selectedEvidence=id;WindowManager.open('forensic-lab');WindowManager.refresh('forensic-lab');} return; }
  const mapLoc=event.target.closest('[data-map-location]'); if(mapLoc){S().ui.activeMap=mapLoc.dataset.mapLocation;StateStore.save();WindowManager.refresh('intel-map');return;}
  const boardNode=event.target.closest('[data-board-node]'); if(boardNode){ const id=boardNode.dataset.boardNode; if(!S().ui.linkStart){S().ui.linkStart=id;NotificationManager.push('LINK MODE',`Pilih kartu kedua untuk menghubungkan ${id}.`);} else if(S().ui.linkStart!==id){S().boardLinks.push({from:S().ui.linkStart,to:id,label:'RELEVANT'});S().ui.linkStart=null;NotificationManager.push('RELASI TERSIMPAN',`${S().boardLinks.at(-1).from} ↔ ${id}`);StateStore.save();} WindowManager.refresh('evidence-board');return; }
  const action=event.target.closest('[data-action]')?.dataset.action; if(!action)return;
  if(action==='skip-boot'){window.clearInterval(window.bootTimer);showLogin();}
  if(action==='fullscreen')requestFullscreen();
  if(action==='dialog-next')DialogueEngine.next();
  if(action==='close-lightbox')$('#lightbox').classList.add('is-hidden');
  if(action==='submit-mission')submitMission();
  if(action==='back-human'){S().ui.selectedHuman=null;WindowManager.refresh('human-db');}
  if(action==='back-vehicle'){S().ui.selectedVehicle=null;WindowManager.refresh('vehicle-db');}
  if(action==='cctv-snapshot'){S().flags.cctvSnapshot=true;revealEvidence('EVD-008');revealEvidence('EVD-009');StateStore.save();WindowManager.refresh('cctv-archive');renderMissionDock();}
  if(action==='toggle-cctv'){S().flags.cctvPlaying=!S().flags.cctvPlaying;WindowManager.refresh('cctv-archive');}
  if(action==='read-plate'){if(!S().flags.cctvSnapshot){NotificationManager.push('FRAME REQUIRED','Ambil snapshot CCTV terlebih dahulu.','warn');return;}S().flags.plateRead='BXR-2041';revealEvidence('EVD-010');StateStore.save();WindowManager.refresh('plate-reader');renderMissionDock();}
  if(action==='analyze-evidence'){const id=S().ui.selectedEvidence;if(id){markFlag('forensic',id);if(id==='EVD-003')revealEvidence('EVD-004');if(id==='EVD-005'){revealEvidence('EVD-006');revealEvidence('EVD-007');}WindowManager.refresh('forensic-lab');renderMissionDock();}}
  if(action==='run-face'){if(S().foundEvidence.includes('EVD-014')){S().flags.faceAnalysis=true;revealEvidence('EVD-015');WindowManager.refresh('face-analysis');}}
  if(action==='start-call'){const id=event.target.closest('[data-call]')?.dataset.call;if(id){addUnique(S().flags.calls,id);if(id==='C-003'){revealEvidence('EVD-005');}StateStore.save();WindowManager.refresh('communications');renderMissionDock();DialogueEngine.show((calls.find(c=>c.id===id)?.lines||[]).map(text=>({speaker:calls.find(c=>c.id===id)?.name||'CONTACT',color:'var(--green)',text})));}}
  if(action==='server-diagnostic'){S().flags.serverChecked=true;revealEvidence('EVD-023');StateStore.save();WindowManager.refresh('server-control');}
  if(action==='add-evidence'){const id=event.target.closest('[data-evidence]')?.dataset.evidence;if(id&&S().foundEvidence.includes(id)){addUnique(S().boardItems,id);StateStore.save();WindowManager.refresh('evidence-board');renderMissionDock();}}
  if(action==='save-note'){S().notes=$('#agent-notes')?.value||'';StateStore.save();NotificationManager.push('CATATAN TERSIMPAN','Catatan agen dicatat di local save.');}
  if(action==='save-game'){StateStore.save('SAVED');NotificationManager.push('PROGRES DISIMPAN','State investigasi tersimpan di perangkat ini.');}
  if(action==='open-reset'){$('#confirm-modal').classList.remove('is-hidden');}
  if(action==='close-confirm')$('#confirm-modal').classList.add('is-hidden');
  if(action==='confirm-reset'){StateStore.reset();$('#confirm-modal').classList.add('is-hidden');WindowManager.windows.forEach((_,id)=>WindowManager.close(id));renderAll();showLogin();NotificationManager.push('DATA DIRESET','Workstation kembali ke state awal.','warn');}
});
document.addEventListener('change',event=>{ const setting=event.target.closest('[data-setting]')?.dataset.setting; if(setting){S().settings[setting]=event.target.checked;StateStore.save();renderAll();if(setting==='master')AudioManager.init();} });
document.addEventListener('click',event=>{ const lightbox=event.target.closest('[data-lightbox]'); if(lightbox)openLightbox(lightbox.dataset.lightbox); });

window.setInterval(()=>{ const now=new Date(); const clock=$('#topbar-time'); if(clock)clock.textContent=now.toLocaleTimeString('id-ID',{hour12:false}); if(WindowManager.windows.has('server-control'))WindowManager.refresh('server-control'); },1000);
window.addEventListener('pointerdown',()=>AudioManager.init(),{once:true});
$('#login-form').addEventListener('submit',event=>{event.preventDefault();const value=$('#agent-name').value.trim();if(value.length<2){$('#login-message').textContent='AUTHENTICATION FAILED // NAMA MINIMAL 2 KARAKTER';AudioManager.alert();return;}S().agentName=value;AudioManager.init();enterDesktop();});
if(S().loggedIn && S().agentName){ startBoot(); } else { startBoot(); }
